style.css:
@-moz-document domain("janitorai.com") {
/* Main chat container */
    .chat-container, 
    .messages-container {
        max-width: 90% !important; /* default ~60%, now 90% */
        width: 90% !important;
        margin: auto !important;
    }

    /* Message bubbles */
    .message,
    .chat-message {
        max-width: 85% !important; /* widen messages */
    }

    /* Input box / textbox */
    textarea,
    .chat-input,
    .chat-textarea {
        max-width: 90% !important;
        width: 90% !important;
        margin: auto !important;
        font-size: 1rem !important; /* optional, slightly larger text */
    }
}
